use super::*;
use std::path::Path;
struct Source;impl dm_preprocess::SourceProvider for Source{fn read(&self,_:&Path)->Result<String,String>{Ok("var/static/list/items=list(1,2)\n".into())}}
#[test]
fn actual_original_semantic_artifact_binds_current_source_before_claim_and_keeps_roles_distinct(){
 let db=Arc::new(crate::query_db::QueryDb::default());let host=db.clone() as Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let front=dm_tree::frontend::build(Path::new("original-semantic-artifact.dme"),&Source,&Default::default(),1).unwrap().with_setting_expression_queries(&host).unwrap();let executor=dm_exec::BuildExecutor::new(1).unwrap();let bodies=dm_tree::frontend::BodyArena::new_typed(&front,dm_codegen_byond::typed_statements_supported_for_capture);let startup=crate::startup::capture_original_with_executor_and_bodies_checked(&front,&[],&executor,&bodies).unwrap();let resolver=startup.resolver(&front,front.snapshot.tree.as_ref()).unwrap();let driver=crate::driver_facts::DriverEvaluator{pure_calls:None,resource_search_context:None,resolver:&resolver,symbols:&startup.plan().symbols};let factory=ParallelEvaluator{factory:&driver,engine:None};let store=InitializerArtifacts::with_limit(16*1024*1024);let reuse=InitializerReuse{store:&store,resolver:&resolver,policy:101,resource_search_context:None};
 let native=crate::initializer_policy::classify_original_startup_with_reuse(&front,&startup,&driver,false,factory,reuse).unwrap();let Some(RuntimeValue::OriginalExpression(first))=&native.writes[0].runtime_value else{panic!("source runtime recipe")};assert!(native.accepted[0].is_some());let recomputed=store.recomputed.load(Ordering::Relaxed);let before=store.hits.load(Ordering::Relaxed);
 let warm=crate::initializer_policy::classify_original_startup_with_reuse(&front,&startup,&driver,false,factory,reuse).unwrap();let Some(RuntimeValue::OriginalExpression(second))=&warm.writes[0].runtime_value else{panic!("source warm runtime recipe")};assert!(Arc::ptr_eq(first,second));assert_eq!(store.recomputed.load(Ordering::Relaxed),recomputed);assert_eq!(store.hits.load(Ordering::Relaxed),before+1);
 let old=crate::initializer_policy::classify_with_reuse_on_executor(&startup.plan().writes,&startup.plan().symbols,factory,false,&executor,reuse).unwrap();assert!(matches!(old.writes[0].runtime_value,Some(RuntimeValue::Expression(_))));assert_eq!(store.hits.load(Ordering::Relaxed),before+1,"owned mode cannot claim an original runtime candidate before declining its source binding");
 let native_again=crate::initializer_policy::classify_original_startup_with_reuse(&front,&startup,&driver,false,factory,reuse).unwrap();assert!(matches!(native_again.writes[0].runtime_value,Some(RuntimeValue::OriginalExpression(_))));assert_eq!(store.hits.load(Ordering::Relaxed),before+1,"required source mode cannot claim an owned runtime candidate");
 let hit=store.hits.load(Ordering::Relaxed);let computed=store.recomputed.load(Ordering::Relaxed);let token=crate::daemon::control::Cancellation::default();let binding=crate::daemon::control::bind_with_deadline(token.clone(),std::time::Instant::now()+std::time::Duration::from_secs(300));token.cancel();assert!(matches!(crate::initializer_policy::classify_original_startup_with_reuse(&front,&startup,&driver,false,factory,reuse),Err(InitializerClassificationFailure::Operational(ref error))if error.kind()==std::io::ErrorKind::Interrupted));drop(binding);assert_eq!(store.hits.load(Ordering::Relaxed),hit);assert_eq!(store.recomputed.load(Ordering::Relaxed),computed);
 assert!(crate::initializer_policy::classify_original_startup_with_reuse(&front,&startup,&driver,false,factory,reuse).is_ok());assert_eq!(store.hits.load(Ordering::Relaxed),hit+1);assert_eq!(db.db().stats(dm_query::Kind(4)).computed,0);
}
